    },
    {
      "endpoint_type": "defluorination",
      "evidence_locator_ids": [
        "S09-E02",
        "S09-E06",
        "S09-E07"
      ],
      "interpretation": "A theoretical organic fluorine loading in the influent AFFF was calculated from quantified PFAAs and compared to measured inorganic fluoride in the liquid effluent to estimate an overall defluorination ratio of ~62.6%. A partial fluorine mole balance indicated that about 28.1% of the expected fluorine (152.9 mmol) was not recovered in measured fluoride, implying an unidentified fluorine-containing fraction (e.g., unmeasured organofluorine species or unmeasured phases such as gas). Gaseous fluoride was not measured, so the defluorination assessment is incomplete.",
      "reported_term": "overall defluorination ratio; fluorine mole balance"
    },
    {
      "endpoint_type": "separation",
      "evidence_locator_ids": [
        "S09-E03"
      ],
      "interpretation": "PFAA mass in the gaseous effluent (stack) was quantified via OTM-45 sampling. The gaseous PFAA mass was on average 42 \u00b5g, corresponding to 0.0003% of the measured influent PFAA mass, demonstrating that only a negligible fraction of parent PFAAs were transferred to the gas phase under the tested SCWO conditions.",
      "reported_term": "gaseous effluent PFAA mass fraction"
    },
    {
      "endpoint_type": "other",
      "evidence_locator_ids": [
        "S09-E04",
        "S09-E05"
